'use client';
import { useEffect, useMemo, useRef, type CSSProperties } from 'react';
import './visuals.css';

/* ------------------------------------------------------------------
   PrecisionGrid — a drafting grid that draws itself on scroll: fine
   1px rules, registration crosshairs and an engraver's tick ruler,
   plus a restrained scroll-linked vertical drift.

   * geometry is generated by index only — no Math.random / Date, so
     SSR and client markup match exactly
   * one rAF loop writes a single SVG transform; it stops at rest
   * pauses offscreen and when the tab is hidden
   * reduced motion / reduce-motion / data-art="off" → static grid
   ------------------------------------------------------------------ */
export type PrecisionGridProps = {
  /** vertical divisions, clamped 4–24 (default 12) */
  cols?: number;
  /** horizontal divisions, clamped 3–16 (default 8) */
  rows?: number;
  /** rendered height in px (default 320); width is always 100% */
  height?: number;
  /** scroll drift in px (default 8) */
  drift?: number;
  /** optional mono coordinate readout */
  label?: string;
  className?: string;
  style?: CSSProperties;
};

const W = 1000;
const H = 400;
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export function PrecisionGrid({
  cols = 12,
  rows = 8,
  height = 320,
  drift = 8,
  label = 'GRID / 00',
  className = '',
  style,
}: PrecisionGridProps) {
  const ref = useRef<SVGSVGElement>(null);
  const driftRef = useRef<SVGGElement>(null);

  const c = clamp(Math.round(cols), 4, 24);
  const r = clamp(Math.round(rows), 3, 16);
  const d = clamp(drift, 0, 24);

  const { vLines, hLines, marks, ticks } = useMemo(() => {
    const vs = Array.from({ length: c + 1 }, (_, i) => i * (W / c));
    const hs = Array.from({ length: r + 1 }, (_, j) => j * (H / r));
    const at = (fx: number, fy: number) => ({
      x: vs[Math.round(fx * c)] ?? W / 2,
      y: hs[Math.round(fy * r)] ?? H / 2,
    });
    const mk = [at(1 / 3, 1 / 3), at(2 / 3, 1 / 3), at(1 / 3, 2 / 3), at(2 / 3, 2 / 3)];
    return { vLines: vs, hLines: hs, marks: mk, ticks: vs };
  }, [c, r]);

  useEffect(() => {
    const svg = ref.current;
    const driftG = driftRef.current;
    if (!svg || !driftG) return;

    const root = document.documentElement;
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
    const motionOff = () =>
      reduce.matches || root.classList.contains('reduce-motion') || root.dataset.art === 'off';

    if (motionOff() || !('IntersectionObserver' in window)) {
      svg.setAttribute('data-drawn', 'true');
      svg.setAttribute('data-active', 'false');
      return;
    }

    let visible = false;
    let cur = 0, target = 0, raf = 0;

    const active = () => visible && !document.hidden && !motionOff();
    const sync = () => svg.setAttribute('data-active', active() ? 'true' : 'false');
    const paint = () => {
      raf = 0;
      if (!active()) return;
      cur += (target - cur) * 0.08;
      driftG.setAttribute('transform', `translate(0 ${((cur - 0.5) * d).toFixed(2)})`);
      if (Math.abs(target - cur) > 0.002) raf = requestAnimationFrame(paint);
    };
    const measure = () => {
      const box = svg.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      target = clamp(1 - (box.top + box.height / 2) / vh, 0, 1);
    };
    const wake = () => {
      sync();
      if (!raf && active()) raf = requestAnimationFrame(paint);
    };
    const halt = () => {
      sync();
      if (raf) { cancelAnimationFrame(raf); raf = 0; }
    };
    const onScroll = () => { measure(); wake(); };
    const onVis = () => (document.hidden ? halt() : wake());
    const onPref = () => (motionOff() ? halt() : wake());

    const io = new IntersectionObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      visible = entry.isIntersecting;
      if (visible) { svg.setAttribute('data-drawn', 'true'); measure(); wake(); }
      else halt();
    }, { threshold: 0.04 });
    io.observe(svg);

    reduce.addEventListener('change', onPref);
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll, { passive: true });
    document.addEventListener('visibilitychange', onVis);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      io.disconnect();
      reduce.removeEventListener('change', onPref);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      document.removeEventListener('visibilitychange', onVis);
    };
  }, [d]);

  const css = { height, ...(style || {}) } as CSSProperties;

  return (
    <svg
      ref={ref}
      className={`pg ${className}`.trim()}
      style={css}
      viewBox={`0 0 ${W} ${H}`}
      preserveAspectRatio="none"
      aria-hidden="true"
      data-drawn="false"
      data-active="false"
    >
      <g ref={driftRef} className="pg-drift">
        <g className="pg-grid">
          {vLines.map((x, i) => (
            <line key={`v${i}`} x1={x} y1="0" x2={x} y2={H}
              className="pg-line pg-line--v" style={{ '--i': i % 12 } as CSSProperties} />
          ))}
          {hLines.map((y, j) => (
            <line key={`h${j}`} x1="0" y1={y} x2={W} y2={y}
              className="pg-line pg-line--h" style={{ '--i': (j + c) % 12 } as CSSProperties} />
          ))}
        </g>
        <g className="pg-marks">
          {marks.map((m, k) => (
            <g key={k} transform={`translate(${m.x} ${m.y})`}>
              <g className="pg-mark" style={{ '--i': k } as CSSProperties}>
                <line x1="-8" y1="0" x2="8" y2="0" className="pg-mark-h" />
                <line x1="0" y1="-8" x2="0" y2="8" className="pg-mark-v" />
                <circle r="2" className="pg-mark-dot" />
              </g>
            </g>
          ))}
        </g>
        <g className="pg-ticks">
          {ticks.map((x, i) => (
            <line key={i} x1={x} y1="0" x2={x} y2={i % 2 ? 5 : 10} className="pg-tick" />
          ))}
        </g>
      </g>
      {label && <text className="pg-label" x="10" y={H - 12}>{label}</text>}
    </svg>
  );
}
